//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_ParseDSEGenComm                                                                                                                                                                                                                                                                
//	CREATOR:		Helgevold - Jan Magne Dybvik
//	NOTE:			TO BE DELETED!
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN								DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-08-15		Jan Magne Dybvik			Initial release (Untested)   
// 1.1.0				2025-09-04		Jan Magne Dybvik			Added config parameter for offset, added engine battery voltage and charging voltage, added general alarm 
//	1.1.1				2026-01-02		Ruben Byman					Bugfix mapping of generator power and mains power, as well as change of DWORD conversion to correct function
//	1.2.0				2026-02-04		Ruben Byman					Added registers from pages 7, 154 and 178. Bugfix comm OK. New structure elements. Added output array for active alarms.
//
//===============================================================================================================================
//
//		FUNKSJONALITET:
//		Parse GenComm data from DSE 8620 MK II Generator controller
//
//===============================================================================================================================
//
//	Example Modbus config:
//
(*
Gen_Requests[0].Enable :=TRUE;
Gen_Requests[0].NodeAdr := 1;
Gen_Requests[0].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Gen_Requests[0].Read.StartAddressLocal :=0;
Gen_Requests[0].Read.StartAddressRemote := 3*256; // Page 3 – Generating Set Status Information
Gen_Requests[0].Read.Count := 7; 

Gen_Requests[1].Enable :=TRUE;
Gen_Requests[1].NodeAdr := 1;
Gen_Requests[1].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Gen_Requests[1].Read.StartAddressLocal :=7;
Gen_Requests[1].Read.StartAddressRemote := 4*256; // Page 4 – Basic Instrumentation
Gen_Requests[1].Read.Count := 66; 

Gen_Requests[2].Enable :=TRUE;
Gen_Requests[2].NodeAdr := 1;
Gen_Requests[2].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Gen_Requests[2].Read.StartAddressLocal :=73;
Gen_Requests[2].Read.StartAddressRemote := 7*256+6; // Page 7 – Accumulated Instrumentation
Gen_Requests[2].Read.Count := 12; 

Gen_Requests[3].Enable :=TRUE;
Gen_Requests[3].NodeAdr := 1;
Gen_Requests[3].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Gen_Requests[3].Read.StartAddressLocal :=85;
Gen_Requests[3].Read.StartAddressRemote := 154*256; // Page 154 – Named Alarm Conditions
Gen_Requests[3].Read.Count := 38; 

Gen_Requests[4].Enable :=TRUE;
Gen_Requests[4].NodeAdr := 1;
Gen_Requests[4].FunctionCode := eFun#Fn03_ReadHoldingRegisters;
Gen_Requests[4].Read.StartAddressLocal :=123;
Gen_Requests[4].Read.StartAddressRemote := 178*256+3; // Page 178 – Internal Analogue Sensor Readings and Unit Info
Gen_Requests[4].Read.Count := 1; 
*)

//Example inline ST for alarm string (Out_GeneratorData.Alm_Active)
(*TON_ChangeString(PT:=T#5s);

IF Num_ActiveAlarms = 0 THEN
	Generators[0].Alm_Active :='No active alarms';
ELSIF TON_ChangeString.Q THEN
	index:=index+1;
	IF index >= Num_ActiveAlarms THEN
		index := 0;
	END_IF;
	TON_ChangeString.In := FALSE;
ELSE
	Generators[0].Alm_Active := Gen_ActiveAlarms[index];
	TON_ChangeString.In:=TRUE;
END_IF;*)
//
//===============================================================================================================================

Wrk_UB :=UPPER_BOUND(Inp_HoldingRegister, 1);
Wrk_LB := LOWER_BOUND(Inp_HoldingRegister, 1);
Wrk_Len := Wrk_UB - Wrk_LB;

// Check for valid array size Page3 Offset
IF Wrk_LB > UINT_TO_DINT(Cfg_Page3_Offset) OR Wrk_UB < UINT_TO_DINT(Cfg_Page3_Offset) + 6 THEN
	HE_ParseGenerator_DSE86xx :=FALSE;
	RETURN;
// Check for valid array size Page4 Offset
ELSIF Wrk_LB > UINT_TO_DINT(Cfg_Page4_Offset) OR Wrk_UB < UINT_TO_DINT(Cfg_Page4_Offset) + 65 THEN
	HE_ParseGenerator_DSE86xx :=FALSE;
	RETURN;
// Check for valid array size Page7 Offset
ELSIF Wrk_LB > UINT_TO_DINT(Cfg_Page7_Offset) OR Wrk_UB < UINT_TO_DINT(Cfg_Page7_Offset) + 11 THEN
	HE_ParseGenerator_DSE86xx :=FALSE;
	RETURN;
// Check for valid array size Page154 Offset
ELSIF Wrk_LB > UINT_TO_DINT(Cfg_Page154_Offset) OR Wrk_UB < UINT_TO_DINT(Cfg_Page154_Offset) + 37 THEN
	HE_ParseGenerator_DSE86xx :=FALSE;
	RETURN;
// Check for valid array size Page178 Offset
ELSIF Wrk_LB > UINT_TO_DINT(Cfg_Page178_Offset) OR Wrk_UB < UINT_TO_DINT(Cfg_Page178_Offset) THEN
	HE_ParseGenerator_DSE86xx :=FALSE;
	RETURN;
// Valid offset data	
ELSE
	HE_ParseGenerator_DSE86xx :=TRUE;
END_IF;

IF Inp_MTCP_ReqError THEN
	Out_CommOK:=FALSE;
	RETURN;
ELSIF Inp_MTCP_ReqCycleDone AND HE_ParseGenerator_DSE86xx THEN
	Out_CommOK:=TRUE;
END_IF;

(**********************************************************************************************
 * PARSE GENERATOR DATA
 **********************************************************************************************)
 //Page 3 (Register 3*256 = 768) - Generating Set Status Information - Read count 7 words
 
// Control Mode
CASE WORD_TO_UINT(Inp_HoldingRegister[Cfg_Page3_Offset + 4]) OF
	
	0: //STOP MODE
	Out_GeneratorData.ControlMode:= 'Stop mode';
	
	1: //AUTO MODE
	Out_GeneratorData.ControlMode:= 'Auto mode';
	
	2: //MANUAL MODE
	Out_GeneratorData.ControlMode:= 'Manual mode';
	
	3: //TEST ON LOAD MODE
	Out_GeneratorData.ControlMode:= 'Test on load mode';
	
	4: //AUTO WITH MANUAL RESTORE
	Out_GeneratorData.ControlMode:= 'Auto with manual restore';
	
	5: //USER CONFIGURATION MODE
	Out_GeneratorData.ControlMode:= 'User configuration mode';
	
	6: //TEST OFF LOAD MODE
	Out_GeneratorData.ControlMode:= 'Test off load mode';
	
	7: //OFF MODE
	Out_GeneratorData.ControlMode:= 'Off mode';
	
END_CASE;

// Errors
WORD2BIT.Wrd :=Inp_HoldingRegister[Cfg_Page3_Offset + 6];
Out_GeneratorData.ControlUnitNotConfigured :=			WORD2BIT.Bit[15];
Out_GeneratorData.ControlUnitFailure :=						WORD2BIT.Bit[13];
Out_GeneratorData.ShutdownAlarmActive :=					WORD2BIT.Bit[12];
Out_GeneratorData.ElectricalTrip :=								WORD2BIT.Bit[11];
Out_GeneratorData.WarningAlarmActive :=					WORD2BIT.Bit[10];
IF Cfg_Telemetry_InUse THEN
	Out_GeneratorData.TelemetryAlarmFlag :=					WORD2BIT.Bit[9];
	Out_GeneratorData.SatelliteTelemetryAlarmFlag :=		WORD2BIT.Bit[8];
END_IF;
Out_GeneratorData.NoFontFile :=									WORD2BIT.Bit[7];
Out_GeneratorData.ControlledShutdownAlarmActive :=WORD2BIT.Bit[6];

Out_GeneratorData.Alm_GeneralAlarm :=Out_GeneratorData.ControlUnitNotConfigured OR 
																	Out_GeneratorData.ControlUnitFailure OR 
																	Out_GeneratorData.ShutdownAlarmActive OR
																	Out_GeneratorData.ElectricalTrip OR
																	Out_GeneratorData.WarningAlarmActive OR
																	(Out_GeneratorData.TelemetryAlarmFlag AND Cfg_Telemetry_InUse) OR
																	(Out_GeneratorData.SatelliteTelemetryAlarmFlag AND Cfg_Telemetry_InUse) OR 
																	Out_GeneratorData.NoFontFile OR
																	Out_GeneratorData.ControlledShutdownAlarmActive;
						
(***********************************************************************************
 * PARSE GENERATOR VALUES
 ***********************************************************************************)
 //Page 4 (Register 4*256 = 1024) - Basic Instrumentation - Read count 66 words

// Motor data
IF Inp_HoldingRegister[Cfg_Page4_Offset + 0] <> 16#FFFF THEN
	Out_GeneratorData.OilPressure := 						WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 0]);
ELSE
	Out_GeneratorData.OilPressure := 						0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 1] <> 16#7FFF THEN
	Out_GeneratorData.CoolantTemperature := 		INT_TO_REAL(WORD_TO_INT(Inp_HoldingRegister[Cfg_Page4_Offset + 1]));
ELSE
	Out_GeneratorData.CoolantTemperature := 		0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 2] <> 16#7FFF THEN
	Out_GeneratorData.OilTemperature := 				INT_TO_REAL(WORD_TO_INT(Inp_HoldingRegister[Cfg_Page4_Offset + 2]));
ELSE
	Out_GeneratorData.OilTemperature := 				0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 3] <> 16#FFFF THEN
	Out_GeneratorData.FuelLevel := 						WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 3]);
ELSE
	Out_GeneratorData.FuelLevel := 						0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 4] <> 16#FFFF THEN
	Out_GeneratorData.ChargeAlternatorVoltage := 	WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 4])*0.1;
ELSE
	Out_GeneratorData.ChargeAlternatorVoltage := 	0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 5] <> 16#FFFF THEN
	Out_GeneratorData.EngineBatteryVoltage := 		WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 5])*0.1;
ELSE
	Out_GeneratorData.EngineBatteryVoltage := 		0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 6] <> 16#FFFF THEN
	Out_GeneratorData.EngineSpeed := 					WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 6]);
ELSE
	Out_GeneratorData.EngineSpeed := 					0;
END_IF;
IF Inp_HoldingRegister[Cfg_Page4_Offset + 7] <> 16#FFFF THEN
	Out_GeneratorData.GeneratorFrequency := 		WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 7])*0.1;
ELSE
	Out_GeneratorData.GeneratorFrequency := 		0;
END_IF;


// Voltage L1-N
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 8];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 9];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorVoltageL1N := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorVoltageL1N:=0;
END_IF;

// Voltage L2-N
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 10];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 11];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorVoltageL2N := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorVoltageL2N:=0;
END_IF;

// Voltage L3-N
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 12];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 13];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorVoltageL3N := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorVoltageL3N:=0;
END_IF;

// Voltage L1-L2
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 14];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 15];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorVoltageL1L2 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorVoltageL1L2:=0;
END_IF;

// Voltage L2-L3
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 16];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 17];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorVoltageL2L3 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorVoltageL2L3:=0;
END_IF;

// Voltage L3-L1
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 18];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 19];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorVoltageL3L1 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorVoltageL3L1:=0;
END_IF;

// Current L1
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 20];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 21];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorCurrentL1 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorCurrentL1:=0;
END_IF;

// Current L2
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 22];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 23];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorCurrentL2 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorCurrentL2:=0;
END_IF;

// Current L3
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 24];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 25];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorCurrentL3 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorCurrentL3:=0;
END_IF;

// Earth Current
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 26];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 27];
IF DWORD2WORD.DWrd <> 16#FFFFF THEN
	Out_GeneratorData.GeneratorEarthCurrent := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorEarthCurrent:=0;
END_IF;

// Power L1
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 28];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 29];
IF DWORD2WORD.DWrd <> 16#7FFFFFFF THEN
	Out_GeneratorData.GeneratorPowerL1 := DINT_TO_REAL(DWORD_TO_DINT(DWORD2WORD.DWrd)) * 0.001;
ELSE
	Out_GeneratorData.GeneratorPowerL1:=0;
END_IF;

// Power L2
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 30];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 31];
IF DWORD2WORD.DWrd <> 16#7FFFF THEN
	Out_GeneratorData.GeneratorPowerL2 := DINT_TO_REAL(DWORD_TO_DINT(DWORD2WORD.DWrd)) * 0.001;
ELSE
	Out_GeneratorData.GeneratorPowerL2:=0;
END_IF;

// Power L3
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 32];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 33];
IF DWORD2WORD.DWrd <> 16#7FFFFFFF THEN
	Out_GeneratorData.GeneratorPowerL3 := DINT_TO_REAL(DWORD_TO_DINT(DWORD2WORD.DWrd)) * 0.001;
ELSE
	Out_GeneratorData.GeneratorPowerL3:=0;
END_IF;


(***********************************************************************************
 * PARSE MAINS VALUES
 ***********************************************************************************)
 // Frequency
 IF Inp_HoldingRegister[Cfg_Page4_Offset + 35] <> 16#FFFF THEN
	Out_GeneratorData.MainsFrequency := WORD_TO_REAL(Inp_HoldingRegister[Cfg_Page4_Offset + 35]) *0.1;
ELSE
	Out_GeneratorData.MainsFrequency:=0;
END_IF;

 // Voltage L1-N
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 36];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 37];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsVoltageL1N := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsVoltageL1N:=0;
END_IF;

 // Voltage L2-N
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 38];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 39];
IF DWORD2WORD.DWrd <> 16#FFFFF THEN
	Out_GeneratorData.MainsVoltageL2N := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsVoltageL2N:=0;
END_IF;

 // Voltage L3-N
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 40];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 41];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsVoltageL3N := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsVoltageL3N:=0;
END_IF;

 // Voltage L1-L2
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 42];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 43];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsVoltageL1L2 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsVoltageL1L2:=0;
END_IF;

 // Voltage L2-L3
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 44];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 45];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsVoltageL2L3 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsVoltageL2L3:=0;
END_IF;

 // Voltage L3-L1
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 46];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 47];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsVoltageL3L1 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsVoltageL3L1:=0;
END_IF;

 // Current L1
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 52];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 53];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsCurrentL1 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsCurrentL1:=0;
END_IF;

// Current L2
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 54];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 55];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsCurrentL2 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsCurrentL2:=0;
END_IF;

// Current L3
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 56];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 57];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsCurrentL3 := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsCurrentL3:=0;
END_IF;

// Earth Current
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 58];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 59];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.MainsEarthCurrent := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.MainsEarthCurrent:=0;
END_IF;

// Power L1
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 60];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 61];
IF DWORD2WORD.DWrd <> 16#7FFFFFFF THEN
	Out_GeneratorData.MainsPowerL1 := DINT_TO_REAL(DWORD_TO_DINT(DWORD2WORD.DWrd)) * 0.001;
ELSE
	Out_GeneratorData.MainsPowerL1:=0;
END_IF;

// Power L2
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 62];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 63];
IF DWORD2WORD.DWrd <> 16#7FFFFFFF THEN
	Out_GeneratorData.MainsPowerL2 := DINT_TO_REAL(DWORD_TO_DINT(DWORD2WORD.DWrd)) * 0.001;
ELSE
	Out_GeneratorData.MainsPowerL2:=0;
END_IF;

// Power L3
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page4_Offset + 64];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page4_Offset + 65];
IF DWORD2WORD.DWrd <> 16#7FFFFFFF THEN
	Out_GeneratorData.MainsPowerL3 := DINT_TO_REAL(DWORD_TO_DINT(DWORD2WORD.DWrd)) * 0.001;
ELSE
	Out_GeneratorData.MainsPowerL3:=0;
END_IF;


(***********************************************************************************
 * PARSE GENERATOR DATA
 ***********************************************************************************)
 //Page 7 (Register 7*256+6 = 1798) - Accumulated Instrumentation - Read count 12 words
 
// Engine run time
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page7_Offset + 0];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page7_Offset + 1];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.RunningHours := DWORD_TO_UDINT(In:=DWORD2WORD.DWrd)/3600;
ELSE
	Out_GeneratorData.RunningHours := 0;
END_IF;

// Generator positive kW hours
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page7_Offset + 2];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page7_Offset + 3];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorPositiveKWh := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorPositiveKWh := 0;
END_IF;

// Generator negative kW hours
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page7_Offset + 4];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page7_Offset + 5];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorNegativeKWh := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorNegativeKWh := 0;
END_IF;

// Generator kVA hours
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page7_Offset + 6];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page7_Offset + 7];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorKVAh := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorKVAh := 0;
END_IF;
 
 // Generator kVAr hours
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page7_Offset + 8];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page7_Offset + 9];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.GeneratorKVArh := DWORD_TO_REAL(In:=DWORD2WORD.DWrd) * 0.1;
ELSE
	Out_GeneratorData.GeneratorKVArh := 0;
END_IF;

 // Generator number of starts
DWORD2WORD.Wrd[1] := Inp_HoldingRegister[Cfg_Page7_Offset + 10];
DWORD2WORD.Wrd[0] := Inp_HoldingRegister[Cfg_Page7_Offset + 11];
IF DWORD2WORD.DWrd <> 16#FFFFFFFF THEN
	Out_GeneratorData.NumOfStart := DWORD_TO_UDINT(In:=DWORD2WORD.DWrd);
ELSE
	Out_GeneratorData.NumOfStart := 0;
END_IF;
 
(***********************************************************************************
* PARSE GENERATOR ALARMS
***********************************************************************************)
//Page 154 (Register 154*256 = 39424) - Named Alarm Conditions - Read count 38 words
Clear(InOut:=ActiveAlarms);
Num_NamedAlarms := WORD_TO_UINT(Inp_HoldingRegister[Cfg_Page154_Offset + 0]);

DispartDigit(In:=Inp_HoldingRegister[Cfg_Page154_Offset + 1], Num:=4, AryOut:=Wrk_NibbleArray[0]);
Wrk_ActiveAlarms[3] := 'Emergency stop';
