* PARSE STORAGE TANK LEVEL
***********************************************************************************)
//Page 178 (Register 178*256+3 = 45571) - Internal Analogue Sensor Readings and Unit Info - Read count 1 word
 
// Level external storage tank
IF Inp_HoldingRegister[Cfg_Page178_Offset] <> 16#7FFF THEN
	Out_GeneratorData.FuelLevelExtTank := 						INT_TO_REAL(WORD_TO_INT(Inp_HoldingRegister[Cfg_Page178_Offset]));
ELSE
	Out_GeneratorData.FuelLevelExtTank := 						0;
END_IF;
 
